-- Track the vector space used for each pgvector embedding so embeddings from
-- different models are never compared during a staged reindex.
ALTER TABLE "Document" ADD COLUMN "embeddingModel" TEXT;

-- Existing vectors were all generated by the former hard-coded model.
UPDATE "Document"
SET "embeddingModel" = 'gemini-embedding-001'
WHERE "embedding" IS NOT NULL;

CREATE INDEX "Document_embeddingModel_idx" ON "Document"("embeddingModel");

-- Migrate only the untouched default. User-selected custom models remain intact.
UPDATE "Settings"
SET "value" = jsonb_set(
  "value"::jsonb,
  '{model}',
  '"openai/gpt-5.6-luna"'::jsonb,
  true
)
WHERE "key" = 'ai_config'
  AND "value"->>'model' = 'openai/gpt-4.1-mini';
